package dev.pocketengine.features.plugins;

import static org.junit.Assert.*;
import android.app.Application;
import dev.pocketengine.core.RunControl;
import java.lang.reflect.Modifier;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.annotation.Config;
import org.robolectric.annotation.SQLiteMode;

/** Real discovery/cleanup SQL fact -> separate native installation review -> original manifest file.
 * Installation itself starts no task, model, process or dependency download. */
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
@SQLiteMode(SQLiteMode.Mode.NATIVE)
public final class McpLocalInstallationNativeTest {
    private static String discover(McpLocalDiscoveryOwnerTest.Fixture x)throws Exception{String id=x.confirm(x.prepare()).getString("taskId");assertEquals("completed",x.finished(id).getString("status"));return id;}
    private static JSONArray selected()throws Exception{return new JSONArray().put("lookup");}
    private static JSONObject review(McpLocalDiscoveryOwnerTest.Fixture x,String task)throws Exception{return x.owner.mcp("prepareLocalMcpInstall",new JSONObject().put("taskId",task).put("tools",selected()));}
    private static JSONObject confirm(McpLocalDiscoveryOwnerTest.Fixture x,JSONObject review)throws Exception{return x.owner.mcp("confirmLocalMcpInstall",new JSONObject().put("reviewId",review.getString("reviewId")).put("reviewDigest",review.getString("reviewDigest")));}
    @Test public void onlyAnActuallyCompletedOriginalDiscoveryCanIssueThePrivateReadOnlyFact()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String ordinary=x.f.tasks.createCapabilityTask("Not a native discovery","").getString("id");assertThrows(SecurityException.class,()->x.f.tasks.completedOwnerMcpDiscoveryForInstallForOwner(ordinary));var pending=x.f.confirmed();x.f.tasks.beginOwnerMcpDiscoveryForOwner(pending,new RunControl());assertThrows(SecurityException.class,()->x.f.tasks.completedOwnerMcpDiscoveryForInstallForOwner(pending.actionId()));assertThrows(SecurityException.class,()->x.owner.mcp("prepareLocalMcpInstall",new JSONObject().put("taskId",pending.actionId()).put("tools",selected()).put("completed",true).put("metadata",new JSONObject())));assertEquals(0,x.f.plugins.snapshot().getJSONArray("plugins").length());for(var ctor:dev.pocketengine.store.TaskStore.OwnerMcpDiscoveryCompleted.class.getDeclaredConstructors())assertTrue(Modifier.isPrivate(ctor.getModifiers()));pending.close();}}
    @Test public void originalCompletedFactIsImmutableAndCannotChangeIssuerOrMintALaunchGrant()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String id=discover(x);var fact=x.f.tasks.completedOwnerMcpDiscoveryForInstallForOwner(id);JSONObject configuration=fact.configurationForOwner(),metadata=fact.metadataForOwner();configuration.getJSONArray("argv").put("forged");metadata.put("serverDigest","0".repeat(64));fact.requireCurrentForOwner(x.f.tasks);assertEquals(3,fact.configurationForOwner().getJSONArray("argv").length());assertNotEquals("0".repeat(64),fact.metadataForOwner().getString("serverDigest"));assertThrows(SecurityException.class,()->fact.requireCurrentForOwner(null));assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));assertEquals(1,x.f.tasks.list().length());}}
    @Test public void separateExplicitInstallationUsesOriginalUuidRevZeroDisabledAndNoGrantsWithoutLaunching()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String id=discover(x);JSONObject review=review(x,id);assertFalse(review.getBoolean("programStarted"));assertFalse(review.getBoolean("executionAuthorized"));assertEquals(McpData.MAX_IMPORTED_TOOLS,review.getInt("maxImportedTools"));assertFalse(review.has("argv"));JSONObject installed=confirm(x,review);assertEquals("local_probe",installed.getString("id"));assertTrue(installed.getString("installationId").matches("[a-f0-9-]{36}"));assertEquals(0,installed.getLong("stateRevision"));assertFalse(installed.getBoolean("enabled"));assertEquals(0,installed.getJSONArray("grants").length());JSONObject tool=installed.getJSONObject("manifest").getJSONArray("tools").getJSONObject(0);assertEquals("mcp",tool.getString("kind"));assertEquals("stdio",tool.getString("transport"));assertFalse(tool.has("endpoint"));assertEquals(review.getString("configurationDigest"),tool.getString("configurationDigest"));assertFalse(installed.getJSONObject("localMcp").has("configuration"));assertFalse(installed.toString().contains("--public-mode"));assertEquals(1,x.f.tasks.list().length());assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));assertEquals(0,x.f.plugins.toolRegistry().length());assertThrows(SecurityException.class,()->confirm(x,review));}}
    @Test public void genericManifestOrJsonCannotSubstituteForTheTypedOwnerInstallReview()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String id=discover(x);JSONObject review=review(x,id);IllegalArgumentException rejected=assertThrows(IllegalArgumentException.class,()->x.f.plugins.handle("install",new JSONObject().put("manifest",review.getJSONObject("manifest"))));assertTrue(rejected.getMessage().contains("不能直接信任"));assertThrows(IllegalArgumentException.class,()->x.f.plugins.handle("confirmLocalMcpInstall",new JSONObject().put("reviewId",review.getString("reviewId")).put("approved",true)));assertEquals(0,x.f.plugins.snapshot().getJSONArray("plugins").length());assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));}}
    @Test public void installedDeclarationsCannotFallThroughToHttpOrLaunchWithoutOriginalTaskBridge()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String id=discover(x);JSONObject installed=confirm(x,review(x,id));String installation=installed.getString("installationId");x.f.plugins.setEnabledReviewed("local_probe",installation,true);JSONObject current=x.f.plugins.snapshot().getJSONArray("plugins").getJSONObject(0);x.f.plugins.setToolGrantReviewed("local_probe",installation,current.getString("grantsDigest"),"lookup",true);assertEquals(0,x.f.plugins.toolRegistry().length());assertThrows(SecurityException.class,()->x.f.plugins.invokeForHost(new JSONObject().put("id","local_probe").put("tool","lookup").put("expectedVersion",installed.getJSONObject("manifest").getString("version")).put("expectedInstallationId",installation).put("arguments",new JSONObject()),new RunControl()));assertEquals(1,x.f.tasks.list().length());assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));}}
    @Test public void anAbsentRaceAfterReviewRefusesTheStaleInstallationRatherThanReplacingTheNewPlugin()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String id=discover(x);JSONObject review=review(x,id),other=x.f.installEcho();assertThrows(SecurityException.class,()->confirm(x,review));assertEquals(other.getString("installationId"),x.f.plugins.snapshot().getJSONArray("plugins").getJSONObject(0).getString("installationId"));assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));}}
    @Test public void originalExistingRevisionZeroCanBeReplacedOnlyByTheStillCurrentNativeReview()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){JSONObject old=x.f.installEcho();String id=discover(x);JSONObject review=review(x,id);assertEquals(0,review.getLong("expectedStateRevision"));JSONObject installed=confirm(x,review);assertNotEquals(old.getString("installationId"),installed.getString("installationId"));assertEquals(0,installed.getLong("stateRevision"));assertFalse(installed.getBoolean("enabled"));assertEquals(0,installed.getJSONArray("grants").length());assertEquals(1,installed.getInt("historyCount"));}}
    @Test public void changingOriginalEnablementInvalidatesTheReviewEvenWhenTheInstallationUuidIsUnchanged()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){JSONObject old=x.f.installEcho();String id=discover(x);JSONObject review=review(x,id);x.f.plugins.setEnabledReviewed("local_probe",old.getString("installationId"),true);assertThrows(SecurityException.class,()->confirm(x,review));assertEquals(old.getString("installationId"),x.f.plugins.snapshot().getJSONArray("plugins").getJSONObject(0).getString("installationId"));}}
    @Test public void sourceChangeAfterTheReviewCannotInstallTheOldProgramAsIfItWereCurrent()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String id=discover(x);JSONObject review=review(x,id);Path file=x.f.android.getFilesDir().toPath().resolve("local-development/checkouts").resolve(x.f.checkout).resolve("files/server.py");Files.write(file,"raise Exception('changed visible source')\n".getBytes(StandardCharsets.UTF_8));assertThrows(SecurityException.class,()->confirm(x,review));assertEquals(0,x.f.plugins.snapshot().getJSONArray("plugins").length());assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));}}
    @Test public void discardedWrongDigestAndUnknownToolSelectionCannotInstallOrGrantAnything()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String id=discover(x);assertThrows(IllegalArgumentException.class,()->x.owner.mcp("prepareLocalMcpInstall",new JSONObject().put("taskId",id).put("tools",new JSONArray().put("not_discovered"))));JSONObject review=review(x,id);assertTrue(x.owner.mcp("discardLocalMcpInstallReview",new JSONObject().put("reviewId",review.getString("reviewId"))).getBoolean("discarded"));assertThrows(SecurityException.class,()->confirm(x,review));JSONObject second=review(x,id);assertThrows(SecurityException.class,()->x.owner.mcp("confirmLocalMcpInstall",new JSONObject().put("reviewId",second.getString("reviewId")).put("reviewDigest","0".repeat(64))));assertEquals(0,x.f.plugins.snapshot().getJSONArray("plugins").length());assertEquals(1,x.f.tasks.list().length());}}
    @Test public void removedActualRuntimeCannotBeReplacedByTheCompletedDiscoveryFact()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String id=discover(x);JSONObject review=review(x,id);x.f.runtime.environmentManager().uninstall(x.f.pack,()->{});assertThrows(IllegalStateException.class,()->confirm(x,review));assertEquals(0,x.f.plugins.snapshot().getJSONArray("plugins").length());}}
    @Test public void aFailedRealProtocolAndCleanupResultStillCannotBecomeAnInstallableCatalogue()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture("  print('not a protocol frame',flush=True)\n")){String id=x.confirm(x.prepare()).getString("taskId");assertEquals("failed",x.finished(id).getString("status"));assertThrows(SecurityException.class,()->x.f.tasks.completedOwnerMcpDiscoveryForInstallForOwner(id));assertEquals(0,x.f.plugins.snapshot().getJSONArray("plugins").length());assertEquals(0,x.f.runtime.environmentManager().describe(x.f.pack).getInt("activeLeases"));}}
    private static void replaceOperationJson(McpLocalDiscoveryOwnerTest.Fixture x,String id,String column,JSONObject replacement)throws Exception{var field=dev.pocketengine.store.TaskStore.class.getDeclaredField("db");field.setAccessible(true);var db=(android.database.sqlite.SQLiteDatabase)field.get(x.f.tasks);android.content.ContentValues values=new android.content.ContentValues();values.put(column,replacement.toString());assertEquals(1,db.update("operations",values,"task_id=? AND operation_id=?",new String[]{id,id}));}
    @Test public void corruptOriginalProcessProofInvalidatesAnAlreadyIssuedFactOnTheActualSqlRow()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String id=discover(x);var fact=x.f.tasks.completedOwnerMcpDiscoveryForInstallForOwner(id);JSONObject receipt=x.f.tasks.ownerMcpDiscoveryForOwner(id).getJSONObject("receipt");receipt.getJSONObject("processReceipt").put("processSessionAbsent",false);replaceOperationJson(x,id,"receipt",receipt);assertThrows(SecurityException.class,()->fact.requireCurrentForOwner(x.f.tasks));assertThrows(SecurityException.class,()->x.f.tasks.completedOwnerMcpDiscoveryForInstallForOwner(id));assertEquals(0,x.f.plugins.snapshot().getJSONArray("plugins").length());}}
    @Test public void corruptOriginalArgvCannotBeAcceptedUnderTheOldSourceConfigurationDigest()throws Exception{try(var x=new McpLocalDiscoveryOwnerTest.Fixture()){String id=discover(x);JSONObject row=x.f.tasks.ownerMcpDiscoveryForOwner(id),job=row.getJSONObject("nativeJob");job.getJSONObject("exact").getJSONObject("payload").getJSONArray("argv").put("changed-public-argument");replaceOperationJson(x,id,"arguments",new JSONObject().put("scope",row.getJSONObject("scope")).put("nativeJob",job));assertThrows(SecurityException.class,()->x.f.tasks.completedOwnerMcpDiscoveryForInstallForOwner(id));assertEquals(0,x.f.plugins.snapshot().getJSONArray("plugins").length());}}
}
